BEGIN;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch12$PT122-S2-Q26$batch12$ AND q.stimulus=$batch12$The obesity invariably associated with some high-fat diets is caused by an absence in these diets of certain nutrients that are necessary for an active metabolism, not by excessive caloric intake. Hence, people on these high-fat diets do not consume too many calories.$batch12$ AND q.prompt=$batch12$The questionable pattern of reasoning in the argument above is most similar to that in which one of the following?$batch12$ AND q.correct_choice=$batch12$C$batch12$) THEN RAISE EXCEPTION 'Question changed: PT122-S2-Q26'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch12$PT122-S2-Q26$batch12$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation row changed: PT122-S2-Q26'; END IF; END $guard$;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch12$PT122-S2-Q26$batch12$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch12$Conclusion$batch12$, $batch12$People on these diets don't consume too many calories.$batch12$), (1, $batch12$Evidence$batch12$, $batch12$The obesity is caused by missing nutrients, not by excess calories.$batch12$), (2, $batch12$Evaluate$batch12$, $batch12$Saying excess calories don't cause the obesity doesn't mean excess calories aren't there. The argument goes from "B isn't the cause" to "B doesn't happen."$batch12$), (3, $batch12$Goal$batch12$, $batch12$Effect caused by A, not B. So B doesn't happen.$batch12$)) v(position,label,body) WHERE q.qid=$batch12$PT122-S2-Q26$batch12$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch12$A$batch12$, $batch12$This goes from correlation to cause.$batch12$), ($batch12$B$batch12$, $batch12$This flips the relationship between beer drinkers and sports fans.$batch12$), ($batch12$C$batch12$, $batch12$Pilot disorientation is caused by daylight disruption, not sleep loss, so pilots don't suffer sleep loss. Same move.$batch12$), ($batch12$D$batch12$, $batch12$This concludes downturns can't be predicted, which isn't the factor ruled out as a cause.$batch12$), ($batch12$E$batch12$, $batch12$This reverses the group relationship, from programmers being math graduates to math training.$batch12$)) v(letter,body) WHERE q.qid=$batch12$PT122-S2-Q26$batch12$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
